INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (369484, 15656, 'The Economic Times', 'en', 'Rupee falls 7 paise to 95.68 against US dollar in early trade', 'https://economictimes.indiatimes.com/markets/forex/forex-news/rupee-falls-7-paise-to-95-68-against-us-dollar-in-early-trade/articleshow/133313508.cms', 'In early trading, the rupee slipped by seven paise, settling at 95.68 against the US dollar. Factors such as soaring crude oil prices and heightened demand for dollars pressured the currency. Forex analysts noted that Brent crude''s price hovering around USD 91 per barrel has led to a surge in dollar demand linked to oil.', 'https://img.etimg.com/photo/msid-133313508,imgsize-11168.cms', '2026-08-18T06:20:40+00:00', '2026-08-18T06:42:15.815575'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
