INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (370244, 15656, 'The Guardian', 'en', 'Oil prices jump after US-Iran ceasefire expires and Trump threatens Oman', 'https://www.theguardian.com/business/2026/aug/18/oil-prices-rise-us-iran-brent-crude-donald-trump', 'Brent crude rises above $90 a barrel for the first time since 30 July after US president tells Tehran to surrender Business live – latest updates Oil prices have risen again after the two-month window to negotiate a peace deal in the US-Israel war on Iran expired on Monday with no end to the conflict in sight. Iran said on Monday that it would take a more aggressive stance if talks with the US failed, while Donald Trump demanded Tehran “put up the white flag of surrender” in an interview with Fox News. Continue reading...', 'https://i.guim.co.uk/img/media/35c3792de76d98515facea91d10823e4dcbba753/421_0_2857_2286/master/2857.jpg?width=140&quality=85&auto=format&fit=max&s=694c2f70816f269cef662e8b9375fad6', '2026-08-18T07:04:12+00:00', '2026-08-18T07:28:54.916314'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (370245, 15656, 'The Guardian', 'en', 'Oil prices rise as US-Iran ceasefire ends; UK wage growth slows amid cost of living squeeze', 'https://www.theguardian.com/business/live/2026/aug/18/oil-prices-rise-us-iran-ceasefire-ends-uk-wage-growth-slows-cost-of-living-squeeze-live-updates', 'Brent crude climbs above $91 a barrel Here is our full story: And here’s the union point of view. TUC general secretary Paul Nowak said: Exploitative zero-hours contracts are endemic in this country, with more than 1.2 million people stuck not knowing how much they’re going to earn each week. That’s why the government must deliver on its promise of a right to guaranteed hours for everyone. Employers are addicted to this one-sided flexibility. But the vast majority of insecure workers have struggled to meet their basic living costs because they haven’t been offered enough hours – and one in thr', 'https://i.guim.co.uk/img/media/482e992ddf09b3cf270883d722b92bbf9d2f1142/458_0_4583_3667/master/4583.jpg?width=140&quality=85&auto=format&fit=max&s=7d80b54ffdeb43a544171b53509aa723', '2026-08-18T07:12:57+00:00', '2026-08-18T07:28:56.567386'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
