INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (370023, 15660, 'The Times of India', 'en', 'TISS names new chief guest weeks after CJI visit sparked ''protest fears''', 'https://timesofindia.indiatimes.com/city/mumbai/tiss-names-new-chief-guest-as-rescheduled-convocation-set-for-aug-22-weeks-after-cji-visit-protest-fears/articleshow/133312883.cms', 'The Tata Institute of Social Sciences has rescheduled its 86th convocation for August 22. Dr C S Pramesh will now be the chief guest at the postponed event. The original ceremony was abruptly cancelled just two days before its scheduled date. Students faced financial losses due to the sudden postponement of their graduation. The institute has assured reimbursement for eligible travel and accommodation expenses incurred.', 'https://static.toiimg.com/photo/msid-133312939,imgsize-123737.cms', '2026-08-18T05:52:21+00:00', '2026-08-18T07:26:42.750812'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
