INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (371479, 15671, 'South China Morning Post', 'en', 'US strikes kept Iran’s fishermen off Hormuz. They can no longer afford to stay idle', 'https://www.scmp.com/news/world/middle-east/article/3364408/us-strikes-kept-irans-fishermen-hormuz-they-can-no-longer-afford-stay-idle', 'Aboard his boat moored along the Strait of Hormuz, Iranian fisherman Mohammad Amin mended a torn fishing net after a long day in waters that have long sustained his livelihood, but are now shadowed by the threat of death. It has been less than a month since the 47-year-old resumed his routine of waking before dawn, heading out to sea and returning hours later with the day’s catch – a routine he had to put on hold during months of fighting between Iran and the United States in and around the...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/18/0fdf8f14-5d84-44b5-b698-fa411687d162_41d7d50e.jpg?itok=U0o2nIeq&v=1787038394', '2026-08-18T07:55:06+00:00', '2026-08-18T08:24:26.019565'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
